#include <bits/stdc++.h>
using namespace std;

int wt[200], val[200];
int dp[200][200];

int knapsack(int i, int wt_left) {
    if (wt_left == 0 || i < 0)
        return 0;

    if (dp[i][wt_left] != -1)
        return dp[i][wt_left];

    int ans = knapsack(i - 1, wt_left);

    if (wt_left - wt[i] >= 0) {
        ans = max(ans,
            knapsack(i - 1, wt_left - wt[i]) + val[i]);
    }

    return dp[i][wt_left] = ans;
}

int main() {
    memset(dp, -1, sizeof(dp));

    int n, w;
    cin >> n >> w;

    for (int i = 0; i < n; i++) {
        cin >> wt[i] >> val[i];
    }

    cout << knapsack(n - 1, w);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int dp[100][100];

int lcs(int i, int j, string &s1, string &s2)
{
    if(i < 0 || j < 0)
        return 0;

    if(dp[i][j] != -1)
        return dp[i][j];

    if(s1[i] == s2[j])
    {
        return dp[i][j] = 1 + lcs(i-1, j-1, s1, s2);
    }

    return dp[i][j] = max(
        lcs(i-1, j, s1, s2),
        lcs(i, j-1, s1, s2)
    );
}

void print_lcs(int i, int j, string &s1, string &s2)
{
    if(i < 0 || j < 0)
        return;

    if(s1[i] == s2[j])
    {
        print_lcs(i-1, j-1, s1, s2);
        cout << s1[i];
    }

    else if(i > 0 && (j == 0 || dp[i-1][j] > dp[i][j-1]))
    {
        print_lcs(i-1, j, s1, s2);
    }

    else
    {
        print_lcs(i, j-1, s1, s2);
    }
}

int main()
{
    memset(dp, -1, sizeof(dp));

    string s1, s2;
    cin >> s1 >> s2;

    int ans = lcs(s1.size()-1, s2.size()-1, s1, s2);

    cout << ans << endl;

    print_lcs(s1.size()-1, s2.size()-1, s1, s2);
    cout << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> arr(100);
int dp[100];

int LIS(int i)
{
    if(dp[i] != -1)
        return dp[i];

    int size = 1;

    for(int j = 0; j < i; j++)
    {
        if(arr[i] > arr[j])
        {
            size = max(size, LIS(j) + 1);
        }
    }

    return dp[i] = size;
}

void print_lis(int i)
{
    for(int j = 0; j < i; j++)
    {
        if(arr[i] > arr[j] && dp[j] + 1 == dp[i])
        {
            print_lis(j);
            break;
        }
    }

    cout << arr[i] << " ";
}

int main()
{
    memset(dp, -1, sizeof(dp));

    int n;
    cin >> n;

    for(int i = 0; i < n; i++)
    {
        cin >> arr[i];
    }

    int size = 0;
    int best_idx = 0;

    for(int i = 0; i < n; i++)
    {
        if(LIS(i) > size)
        {
            size = LIS(i);
            best_idx = i;
        }
    }

    cout << size << endl;

    print_lis(best_idx);
    cout << endl;

    return 0;
}

